// 1. Natural idempotency — best. The operation is inherently repeatable.
await db.query(
  `UPDATE positions SET quantity = $1 WHERE account = $2 AND symbol = $3`,
  [absoluteQuantity, account, symbol]);
// Setting an absolute value twice = setting it once.
// Contrast: `quantity = quantity + $1` is NOT idempotent.

// 2. Deduplication table — general purpose.
await db.transaction(async tx => {
  const inserted = await tx.query(
    `INSERT INTO processed_events (event_id) VALUES ($1) ON CONFLICT DO NOTHING`,
    [event.id]);
  if (inserted.rowCount === 0) return;   // already processed
  await applyEffect(tx, event);          // SAME transaction — essential
});

